- (void)submitRows:(NSArray*)rows{for(NSDictionary *candidate in rows){if(candidate[@"linkedTask"]){continue;}NSString *key=PVXRowID(candidate);if([self.pending containsObject:key])continue;[self.pending addObject:key];self.feedback.text=@"正在提交下载请求，任务落盘后显示确认…";__weak typeof(self)weak=self;PVXSubmitMedia(candidate,^(NSDictionary *submitted,NSString *error){PVXManager *self=weak;if(!self)return;[self.pending removeObject:key];if(error.length||!submitted){self.feedback.text=error?:@"请求未写入";PVXAlert(@"下载未提交",error?:@"请求未能写入下载队列。");}else{self.submissions[key]=submitted;PVXRememberSource(candidate,submitted);self.feedback.text=@"请求已写入队列，可切到“下载”查看接收与进度；不会自动跳页。";}[self readData];});}[self readData];}
