- (void)openParallelSettings{UIAlertController*a=[UIAlertController alertControllerWithTitle:@"并行下载影片数量" message:@"默认 15 部，最高 15 部" preferredStyle:UIAlertControllerStyleActionSheet];for(NSNumber*n in @[@5,@8,@10,@12,@15]){NSString*t=[NSString stringWithFormat:@"%@ 部",n];[a addAction:[UIAlertAction actionWithTitle:t style:UIAlertActionStyleDefault handler:^(UIAlertAction*x){PVXSetParallelLimit(n.integerValue);self.feedback.text=[NSString stringWithFormat:@"并行下载上限已设为 %@ 部",n];}]];}[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.sourceView=self.moreButton;a.popoverPresentationController.sourceRect=self.moreButton.bounds;[(UIViewController*)self presentViewController:a animated:YES completion:nil];}
- (void)openSettings{UIAlertController*a=[UIAlertController alertControllerWithTitle:@"下载设置" message:@"默认保存位置" preferredStyle:UIAlertControllerStyleActionSheet];BOOL photos=PVXAutoSavePhotos(),files=[NSUserDefaults.standardUserDefaults boolForKey:@"com.crctdd.pyvideo.plus.autoFiles"];[a addAction:[UIAlertAction actionWithTitle:photos?@"默认保存相册：开":@"默认保存相册：关" style:UIAlertActionStyleDefault handler:^(UIAlertAction*x){PVXSetAutoSavePhotos(!photos);[self openSettings];}]];[a addAction:[UIAlertAction actionWithTitle:files?@"默认保存文件：开":@"默认保存文件：关" style:UIAlertActionStyleDefault handler:^(UIAlertAction*x){[NSUserDefaults.standardUserDefaults setBool:!files forKey:@"com.crctdd.pyvideo.plus.autoFiles"];[self openSettings];}]];[a addAction:[UIAlertAction actionWithTitle:[NSString stringWithFormat:@"并行下载：%@ 部",@(PVXParallelLimit())] style:UIAlertActionStyleDefault handler:^(UIAlertAction*x){[self openParallelSettings];}]];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.sourceView=self.moreButton;a.popoverPresentationController.sourceRect=self.moreButton.bounds;[self presentViewController:a animated:YES completion:nil];}
- (CGSize)collectionView:(UICollectionView*)v layout:(UICollectionViewLayout*)layout sizeForItemAtIndexPath:(NSIndexPath*)p{CGFloat w=floor((v.bounds.size.width-24.0)/2.0);return CGSizeMake(MAX(120,w),MAX(190,floor(w*1.28)));}
- (NSInteger)collectionView:(UICollectionView*)v numberOfItemsInSection:(NSInteger)section{return self.collapsed?0:self.rows.count;}
- (UICollectionViewCell*)collectionView:(UICollectionView*)v cellForItemAtIndexPath:(NSIndexPath*)p{PVXGridCell*c=[v dequeueReusableCellWithReuseIdentifier:@"grid" forIndexPath:p];NSDictionary*r=self.rows[p.item];c.identity=PVXRowID(r);c.selectionIcon.hidden=!self.selecting||![self.selection containsObject:c.identity];NSDictionary *presentation=PVXTaskPresentation(r);c.title.text=PVXText(r[@"title"]);c.status.text=presentation[@"status"];c.badge.text=presentation[@"format"];NSString *quality=PVXText(r[@"quality"]);if(!quality.length&&[r[@"height"] integerValue]>0)quality=[NSString stringWithFormat:@"%ldp",(long)[r[@"height"] integerValue]];c.details.text=[NSString stringWithFormat:@"%@%@",PVXText(presentation[@"size"]),quality.length?[NSString stringWithFormat:@" · %@",quality]:@""];c.cover.image=[UIImage systemImageNamed:[r[@"kind"] isEqual:@"image"]?@"photo":@"play.rectangle"];__weak PVXGridCell*w=c;PVXFetchTaskThumbnail(r,^(UIImage*i){if([w.identity isEqual:PVXRowID(r)]&&i)w.cover.image=i;});if([r[@"url"] isKindOfClass:NSString.class]){PVXFetchMediaMetadata(r,^(NSDictionary *m){if(![w.identity isEqual:PVXRowID(r)])return;UIImage *i=m[@"thumbnail"];if([i isKindOfClass:UIImage.class])w.cover.image=i;NSString *q=m[@"quality"];NSString *size=m[@"sizeText"];if([q isKindOfClass:NSString.class]&&q.length)w.details.text=[NSString stringWithFormat:@"%@ · %@",size.length?size:presentation[@"size"],q];});}return c;}
- (void)collectionView:(UICollectionView*)v didSelectItemAtIndexPath:(NSIndexPath*)p{NSDictionary*r=self.rows[p.item];if(self.selecting)[self toggleRow:r];else[self toggleTransfer:r];}
- (BOOL)tableView:(UITableView*)t canEditRowAtIndexPath:(NSIndexPath*)p{return !self.selecting;}
- (UISwipeActionsConfiguration*)tableView:(UITableView*)t trailingSwipeActionsConfigurationForRowAtIndexPath:(NSIndexPath*)p{if(self.selecting||p.row<0||(NSUInteger)p.row>=self.rows.count)return nil;NSDictionary*r=self.rows[p.row],*task=r[@"linkedTask"]?:r;if(!task[@"id"])return nil;__weak typeof(self)w=self;UIContextualAction*d=[UIContextualAction contextualActionWithStyle:UIContextualActionStyleDestructive title:@"删除" handler:^(UIContextualAction*a,UIView*v,void(^done)(BOOL)){done(YES);PVXDeleteTasks(@[task],^(NSString*e){if(e.length)PVXAlert(@"删除未完成",e);[w readData];});}];d.image=[UIImage systemImageNamed:@"trash"];UISwipeActionsConfiguration*c=[UISwipeActionsConfiguration configurationWithActions:@[d]];c.performsFirstActionWithFullSwipe=YES;return c;}
@end
static __weak PVXManager *PVXManagerVisible;
void PVXShowDownloads(void){if(!NSThread.isMainThread){dispatch_async(dispatch_get_main_queue(),^{PVXShowDownloads();});return;}if(PVXManagerVisible){if(PVXManagerVisible.viewIfLoaded.window){[PVXManagerVisible readData];return;}PVXManagerVisible=nil;}WKWebView *web=PVXCurrentWebView();if(web)PVXSetCollectionWebView(web);UIViewController *p=PVXPresenter();if(!p||p.isBeingDismissed||p.isBeingPresented)return;PVXManager *v=[PVXManager new];v.modalPresentationStyle=UIModalPresentationPageSheet;v.sheetPresentationController.detents=@[UISheetPresentationControllerDetent.largeDetent];v.sheetPresentationController.prefersGrabberVisible=YES;v.sheetPresentationController.preferredCornerRadius=16;PVXManagerVisible=v;[p presentViewController:v animated:YES completion:nil];}
